CREATE TABLE `training_archive_manual_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `target_user_id` bigint NOT NULL COMMENT '被变更学员用户ID',
  `target_user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '被变更学员姓名',
  `field_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '变更字段名',
  `before_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更前值',
  `after_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更后值',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更备注',
  `operator_id` bigint NOT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除（业务上禁止删除，仅框架逻辑删除）',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_taml_target_user` (`target_user_id`),
  KEY `idx_taml_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='档案人工变更日志表';
