  KEY `idx_tcat_tenant` (`tenant_id`),
  KEY `idx_tcat_type_code` (`type`,`code`)
) ENGINE=InnoDB AUTO_INCREMENT=734 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资源中心分类表（文档/视频/试题共用）';
