CREATE TABLE `training_cert_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模板ID',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板编码',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '证书类型：1-普通电子证书 2-联合认证证书',
  `template_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板背景图地址',
  `content_json` text COLLATE utf8mb4_unicode_ci COMMENT '模板字段配置（JSON）',
  `valid_days` int DEFAULT NULL COMMENT '证书有效天数',
  `review_days` int DEFAULT NULL COMMENT '到期前复审提醒天数',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0-启用 1-停用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tct_code` (`code`),
  KEY `idx_tct_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='培训证书模板表';
