CREATE TABLE `training_class` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '培训班ID',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '培训班编码（开班后自动生成，如 TB{id}）',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '培训班名称',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '培训类型：1岗前培训 2复工培训 3工人技能培训 4质检专项 5安全管理 6特种作业持证 7学徒进阶培训班 8复合型人才专项培训班',
  `project_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联工程项目编号（岗前/复工培训建议必填，供上岗资格核查）',
  `project_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联工程项目名称',
  `target_condition` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参训对象筛选条件（JSON，如岗位/工种/部门/班组/成长等级）',
  `target_posts` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '定岗（结业后对应岗位，JSON数组，四定-定岗）',
  `start_time` datetime DEFAULT NULL COMMENT '开班时间',
  `deadline` datetime DEFAULT NULL COMMENT '培训截止时间',
  `course_count` int NOT NULL DEFAULT '0' COMMENT '绑定课程数（冗余）',
  `student_count` int NOT NULL DEFAULT '0' COMMENT '在班学员数（冗余）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1进行中 2已完成 3已取消',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tc_status_type` (`status`,`type`),
  KEY `idx_tc_project` (`project_id`),
  KEY `idx_tc_deadline` (`deadline`),
  KEY `idx_tc_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='培训班表';
