  `version` int NOT NULL DEFAULT '1' COMMENT '版本号（从1递增）',
  `is_current` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否当前生效版本',
  `category_id` bigint DEFAULT NULL COMMENT '课程分类ID（复用资源中心 categories，type=course，预留）',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程编码（审核通过后锁定）',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程标题',
  `subtitle` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程副标题',
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT '课程简介',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `level` tinyint DEFAULT NULL COMMENT '课程级别：1初级 2中级 3高级',
  `course_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '成长等级标记：APPRENTICE学徒 JUNIOR初级工 INTERMEDIATE中级工 SENIOR高级工 TECHNICIAN技师 SENIOR_TECHNICIAN高级技师（对应 training_growth_level 六级字典）',
  `credit` decimal(5,2) DEFAULT NULL COMMENT '课程学分',
  `duration_minutes` int DEFAULT NULL COMMENT '课程总时长（分钟）',
  `industry` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '面向行业',
  `applicable_posts` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '适用岗位/工种（JSON数组）',
  `learn_domain_codes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学习域/课程组编码（按适用岗位工种自动匹配，逗号分隔，* 表示全域）',
  `owner_flag` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源归属标识（对外部资源中心 owner_flag 的快照，占位）',
  `biz_tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务标签（JSON数组，如["岗前培训","复工强制"]）',
  `is_required` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否必修',
  `is_composite` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否复合课程',
  `composite_tags` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复合课程子模块标签（JSON数组，如["管道安装","防腐保温"]）',
  `exam_id` bigint DEFAULT NULL COMMENT '关联结课考试试卷ID（模块三预留）',
  `exam_start_time` datetime DEFAULT NULL COMMENT '结课考试开始时间（模块三考试与认证联动）',
  `exam_end_time` datetime DEFAULT NULL COMMENT '结课考试结束时间（模块三考试与认证联动）',
  `lecturer` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主讲教师',
  `lecturer_brief` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '讲师简介',
  `media_type` tinyint NOT NULL DEFAULT '0' COMMENT '内容类型：0未绑定 1文档 2视频 3图文（由媒资汇总）',
  `media_count` int NOT NULL DEFAULT '0' COMMENT '媒资数量（冗余）',
  `comment_count` int NOT NULL DEFAULT '0' COMMENT '评论数（冗余）',
  `audit_count` int NOT NULL DEFAULT '0' COMMENT '审核次数（冗余）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0草稿 1待审核 2审核通过(待上架) 3已上架 4已下架',
  `submitter_id` bigint DEFAULT NULL COMMENT '最近提交人ID',
  `reviewer_id` bigint DEFAULT NULL COMMENT '最近审核完成人ID',
  `reviewed_at` datetime DEFAULT NULL COMMENT '最近审核完成时间',
  `submitted_at` datetime DEFAULT NULL COMMENT '最近提交时间',
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近驳回原因（驳回必填）',
  `last_audit_time` datetime DEFAULT NULL COMMENT '最近审核时间',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_training_course_root` (`root_id`,`is_current`),
  KEY `idx_training_course_status` (`status`),
  KEY `idx_training_course_category` (`category_id`),
  KEY `idx_training_course_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程表（含版本链）';
