CREATE TABLE `training_course_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `action` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动作：SUBMIT提交审核 WITHDRAW撤审 APPROVE通过 REJECT驳回 ONLINE上架 OFFLINE下架 PUBLISH发布新版本',
  `from_status` tinyint DEFAULT NULL COMMENT '操作前状态',
  `to_status` tinyint DEFAULT NULL COMMENT '操作后状态',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名快照',
