CREATE TABLE `training_course_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父级分类ID(0=一级域)',
  `level` tinyint NOT NULL DEFAULT '1' COMMENT '层级:1域 2组 3课',
  `biz_category` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类别/适用工程队(域级)',
  `std_hours` int DEFAULT NULL COMMENT '标准学时(课程级)',
  `is_required` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否必修(课程级)',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类编码（唯一标识，对接资源中心时使用）',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态:active启用 inactive停用',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tcc_name` (`name`),
  KEY `idx_tcc_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=197 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程分类表（13类行业种子，资源中心 categories 占位）';
