DROP TABLE IF EXISTS `training_course_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_course_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父评论ID（0=一级评论，预留回复能力）',
  `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容（≤500字）',
  `user_id` bigint DEFAULT NULL COMMENT '评论用户ID',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评论用户姓名快照',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1正常 2已删除（软删留痕）',
  `deleted_by` bigint DEFAULT NULL COMMENT '删除人ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间',
  `delete_reason` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '删除原因（管理端治理占位，如"违规内容"）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tcc_course` (`course_id`),
  KEY `idx_tcc_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

