CREATE TABLE `training_growth_level` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级编码(唯一)：APPRENTICE学徒 JUNIOR初级工 INTERMEDIATE中级工 SENIOR高级工 TECHNICIAN技师 SENIOR_TECHNICIAN高级技师',
  `level_no` int NOT NULL COMMENT '等级序号：1学徒 2初级工 3中级工 4高级工 5技师 6高级技师',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级名称',
  `position_desc` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '定位描述',
  `work_permission` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '独立作业权限',
  `max_apprentice` int NOT NULL DEFAULT '0' COMMENT '带徒上限(人)',
  `need_review` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否需人工评审：0否 1是',
  `reference` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参考对标',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  UNIQUE KEY `uk_level_no` (`level_no`),
  KEY `idx_name` (`name`),
  KEY `idx_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成长等级表（六级人才成长体系字典）';
/*!40101 SET character_set_client = @saved_cs_client */;

