INSERT INTO `training_growth_level` VALUES (7,'APPRENTICE',1,'学徒','入门，跟随作业','否（全程监护）',0,_binary '\0','初级工前',1,'最低等级：处于入门跟随阶段，须在师傅监护下作业，不可带徒','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1),(8,'JUNIOR',2,'初级工','能在监督下完成单项工序','限简单工序',0,_binary '\0','五级/初级',2,'可承担简单工序作业但需监督，不可带徒','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1),(9,'INTERMEDIATE',3,'中级工','独立完成主体工序','是（本工种常规）',0,_binary '\0','四级/中级',3,'可独立完成本工种常规作业，尚不具备带徒资格','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1),(10,'SENIOR',4,'高级工','处理复杂工况与缺陷返修','是（含复杂工况）',2,_binary '\0','三级/高级',4,'可带 2 名学徒，负责复杂工况与缺陷返修','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1),(11,'TECHNICIAN',5,'技师','工艺优化、班组技术负责','是+技术决策',5,_binary '\0','二级/技师',5,'班组技术负责人，可带 5 名学徒，参与工艺优化','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1),(12,'SENIOR_TECHNICIAN',6,'高级技师','跨工种攻关、标准与课程编写','是+方案审核',99,_binary '','一级/高级技师',6,'最高等级：跨工种技术攻关、标准与课程编写，晋级需人工评审，带徒不设上限','admin','2026-09-10 09:31:52','','2026-09-10 09:31:52',_binary '\0',1);
