/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_job` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '岗位工种ID',
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种编码：OP-* 操作序列 / TC-* 技术序列 / QC-* 质检检测序列 / MG-* 管理序列 / SP-* 支持序列',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种名称',
  `seq_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '序列编码：OP操作 TC技术 QC质检检测 MG管理 SP支持',
  `seq_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '序列名称',
  `biz_category` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类目（对应文档章节号，如 一/二/三/二十三）',
  `learn_domain` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学习域/课程组（原始文本，如 A,B01-B03 / 全域）',
  `learn_domain_codes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规范化学习域/课程组编码（逗号分隔，关联 training_course_category.code；* 表示全域）',
  `key_skills` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关键技能',
  `max_level` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最高成长等级（关联 training_growth_level.code：TECHNICIAN技师 / SENIOR_TECHNICIAN高级技师）',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态：active 启用 / disabled 停用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_seq` (`seq_code`),
  KEY `idx_max_level` (`max_level`),
  KEY `idx_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='岗位工种字典表（云培训学院基础数据字典）';
/*!40101 SET character_set_client = @saved_cs_client */;

