DROP TABLE IF EXISTS `training_job_cert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_job_cert` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '资格证ID',
  `job_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种编码（关联 training_job.code）',
  `job_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种名称（冗余，便于展示）',
  `cert_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资格证名称',
  `is_required` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否必须持证上岗：0否 1是',
  `valid_months` int DEFAULT NULL COMMENT '有效期（月），NULL 表示长期有效',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_cert` (`job_code`,`cert_name`),
  KEY `idx_job_code` (`job_code`),
  KEY `idx_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工种资格证要求表（持证上岗校验依据）';
/*!40101 SET character_set_client = @saved_cs_client */;

