CREATE TABLE `training_learning_map` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学习地图ID',
  `job_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种编码（关联 training_job.code）',
  `job_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种名称（冗余，便于展示）',
  `stage` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成长阶段：entry入门段(L1→L2) / core核心段(L2→L3) / advanced进阶段(L3→L4) / technician技师段(L4→L5)',
  `stage_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '阶段名称（入门段(L1→L2) 等）',
  `stage_no` int NOT NULL DEFAULT '1' COMMENT '阶段序号：1入门 2核心 3进阶 4技师',
  `course_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程编码（关联 training_course_category.code，level=3 课程级）',
  `course_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程名称（冗余，便于展示）',
  `is_required` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否必修：0否 1是',
  `sort` int NOT NULL DEFAULT '0' COMMENT '阶段内排序',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_stage_course` (`job_code`,`stage`,`course_code`),
  KEY `idx_job_code` (`job_code`),
  KEY `idx_stage` (`stage`),
  KEY `idx_course_code` (`course_code`),
  KEY `idx_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工种学习地图表（阶段化课程路径）';
