  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  `lecturer_user_id` bigint DEFAULT NULL,
  `visibility` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enterprise',
  `audit_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `audit_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `replay_enabled` tinyint NOT NULL DEFAULT '1',
