CREATE TABLE `training_qualification_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录 ID',
  `user_id` bigint DEFAULT NULL COMMENT '平台用户 ID（人员不存在时为空）',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核查输入/匹配到的姓名',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '核查输入的手机号',
  `qualified` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否具备上岗资格',
  `passed_posts` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通过岗位（JSON 数组，如 ["管道工","防腐工"]）',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结论说明',
  `detail_json` text COLLATE utf8mb4_unicode_ci COMMENT '核查明细（培训班列表 JSON）',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tqr_mobile` (`mobile`),
  KEY `idx_tqr_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='上岗资格核查历史记录';
