/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_question` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '试题ID',
  `qtype` tinyint NOT NULL COMMENT '题型：1单选 2多选 3判断 4实操问答 5案例分析',
  `stem` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题干',
  `options_json` text COLLATE utf8mb4_unicode_ci COMMENT '选项JSON：[{"key":"A","text":"...","isCorrect":true}]',
  `answer` text COLLATE utf8mb4_unicode_ci COMMENT '正确答案（判断/问答/案例分析存文本）',
  `analysis` text COLLATE utf8mb4_unicode_ci COMMENT '解析',
  `difficulty` tinyint NOT NULL DEFAULT '2' COMMENT '难度：1易 2中 3难',
  `category_id` bigint DEFAULT NULL COMMENT '所属分类ID（资源分类question类型，支持三级）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1启用 2停用（被引用禁物理删除可停用）',
  `creator_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `creator_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人姓名',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tq_qtype` (`qtype`),
  KEY `idx_tq_status` (`status`),
  KEY `idx_tq_tenant` (`tenant_id`),
  KEY `idx_tq_category` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='试题表';
/*!40101 SET character_set_client = @saved_cs_client */;

