/*!40000 ALTER TABLE `training_question` DISABLE KEYS */;
INSERT INTO `training_question` VALUES (1,1,'（难度：易）公司防腐保温业务的主要服务对象是下列哪一类？','[{\"key\":\"A\",\"text\":\"石化、化工、电力、市政供热等工业装置\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"家用电器制造车间\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"汽车整车装配线\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"食品冷链零售门店\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(2,1,'（难度：易）下列属于管道外防腐主流工艺的是？','[{\"key\":\"A\",\"text\":\"3PE 三层聚乙烯防腐\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"阳极氧化处理\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电镀锌\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"表面渗碳\",\"isCorrect\":false}]','A','',2,608,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(3,1,'（难度：易）公司产品线中的“保温”主要解决什么问题？','[{\"key\":\"A\",\"text\":\"减少热量散失、防止冻凝与烫伤\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"提高金属导电性\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"增加结构承载能力\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"降低材料密度\",\"isCorrect\":false}]','A','',2,627,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(4,1,'（难度：易）岩棉、玻璃棉、硅酸铝棉属于下列哪类材料？','[{\"key\":\"A\",\"text\":\"绝热保温材料\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"防腐涂料\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"结构钢材\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"密封胶粘剂\",\"isCorrect\":false}]','A','',2,628,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(5,1,'（难度：易）环氧粉末（FBE）主要应用于下列哪个部位？','[{\"key\":\"A\",\"text\":\"管道及管件外表面的熔结防腐涂层\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"混凝土外加剂\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电缆绝缘层\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"建筑幕墙玻璃\",\"isCorrect\":false}]','A','',2,610,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(6,1,'（难度：易）公司承接的防腐保温工程项目，业务链条通常起始于？','[{\"key\":\"A\",\"text\":\"现场勘查与需求确认\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"竣工结算\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"备品备件采购\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"人员招聘\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(7,1,'（难度：易）下列哪一项不属于防腐保温工程的典型客户行业？','[{\"key\":\"A\",\"text\":\"石油化工\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"电力热电\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"市政供热\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"服装零售\",\"isCorrect\":true}]','D','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(8,1,'（难度：易）3PE 防腐层中的“PE”指的是？','[{\"key\":\"A\",\"text\":\"聚乙烯\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"聚酯\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"环氧树脂\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"聚氨酯\",\"isCorrect\":false}]','A','',2,609,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(9,1,'（难度：中）公司对外宣传中的“一体化解决方案”通常指？','[{\"key\":\"A\",\"text\":\"材料供应 + 施工 + 验收全过程服务\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"仅提供材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"仅提供方案设计\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"仅提供物流运输\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(10,1,'（难度：中）了解客户需求时，首要关注的信息通常是？','[{\"key\":\"A\",\"text\":\"介质温度、压力与腐蚀环境等工况条件\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"客户办公电脑的品牌\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"厂区绿化面积\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"员工平均年龄\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(11,1,'（难度：易）公司防腐保温业务通常包含下列哪些产品与服务？','[{\"key\":\"A\",\"text\":\"防腐涂料供应\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"绝热保温材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场防腐保温施工\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"工程验收技术服务\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(12,1,'（难度：中）选择防腐方案时需要重点考虑的因素有哪些？','[{\"key\":\"A\",\"text\":\"介质温度与运行工况\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"环境腐蚀性与敷设方式\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"设计使用寿命\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"管道外表面油漆颜色\",\"isCorrect\":false}]','A','',2,701,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(13,1,'（难度：易）保温工程的常见应用部位包括？','[{\"key\":\"A\",\"text\":\"蒸汽与热水管道\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"储罐与塔器\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"换热设备\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"办公桌椅\",\"isCorrect\":false}]','A','',2,627,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(14,1,'（难度：易）下列属于绝热保温材料的有哪些？','[{\"key\":\"A\",\"text\":\"岩棉\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"玻璃棉\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"硅酸铝棉\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"环氧富锌底漆\",\"isCorrect\":false}]','A','',2,628,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(15,1,'（难度：中）与客户洽谈项目时通常需要明确的信息有哪些？','[{\"key\":\"A\",\"text\":\"工程量与工期要求\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"执行的技术标准\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场施工条件\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"结算与付款方式\",\"isCorrect\":false}]','A','',2,709,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-14 17:11:07',_binary '\0',1),(16,1,'（难度：易）防腐与保温是两种功能不同的工程措施：前者防止腐蚀，后者减少热损失。','','对','两者目标不同，常配合使用但不可相互替代。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(17,1,'（难度：易）3PE 防腐层由环氧粉末底层、胶粘剂中间层和聚乙烯面层三层构成。','','对','这是 3PE 的标准结构。',2,609,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(18,1,'（难度：易）保温材料可以脱离介质温度随意选型，与工况无关。','','错','材料耐温等级必须匹配介质温度，否则会失效甚至碳化。',2,628,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(19,1,'（难度：易）FBE 是环氧粉末涂层的英文缩写。','','对','FBE 即 Fusion Bonded Epoxy。',2,610,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(20,1,'（难度：易）公司的业务仅涉及涂料销售，不包含现场施工。','','错','公司业务包含现场防腐保温施工与验收技术服务。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(21,1,'（难度：易）石化、电力、市政供热等行业都属于防腐保温工程的典型服务领域。','','对','这些行业存在大量需防腐与保温的管道和设备。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(22,1,'（难度：易）熟悉公司产品线有助于现场准确识别材料与工艺。','','对','识别材料是判断工艺与质量的前提。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(23,1,'（难度：易）保温工程的目的一是减少热损失，二是防止管道冬季冻凝。','','对','防冻防凝是保温的重要功能之一。',2,627,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(24,1,'（难度：中）客户的行业背景与防腐方案选择没有关系。','','错','行业决定介质与腐蚀环境，直接影响方案选择。',2,701,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(25,1,'（难度：中）工程类项目通常需要现场勘查后再确定技术方案。','','对','现场条件（敷设方式、环境、空间）是方案确定的重要依据。',2,701,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:44:14',_binary '\0',1),(26,4,'（难度：中）简述公司防腐保温业务的主要服务对象与典型应用场景。','','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(27,4,'（难度：中）简述防腐与保温两类工程措施的目的差异。','','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(28,4,'（难度：易）列举公司产品线中至少三类材料并说明其用途。','','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。',2,570,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(29,4,'（难度：中）承接防腐保温项目时，前期需要向客户确认哪些关键信息？','','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。',2,709,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(30,4,'（难度：中）为什么现场人员需要了解公司业务全景与产品线？','','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。',2,571,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(31,5,'（难度：中）某化工厂反映“蒸汽管道外面包了保温棉，但人员仍被烫伤”。请分析可能原因并提出处理思路。','','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。',2,631,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(32,4,'（难度：易）项目部准备承接一个新建化工厂的蒸汽管道保温工程，请列出开工前需要收集的基本信息。','','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。',2,631,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(33,5,'（难度：中）现场新员工把岩棉当成了“防腐涂料”准备刷在设备表面。请指出错误并说明正确做法。','','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。',2,628,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(34,5,'（难度：中）客户问：“你们的 3PE 防腐和普通刷漆有什么区别？”请用通俗语言解释。','','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。',2,609,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(35,5,'（难度：中）某市政供热工程要求必须在采暖季前完工，作为刚入职的现场人员，你应重点关注哪些业务环节？','','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。',2,707,1,1,'OPENLAB','1','2026-09-14 16:48:14','1','2026-09-15 16:59:23',_binary '\0',1),(36,1,'【功能验证-勿留】AI导入分类测试题1','[{\"key\":\"A\",\"text\":\"选项一\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"选项二\",\"isCorrect\":false}]','A','',2,569,1,1,'OPENLAB','1','2026-09-14 17:06:15','1','2026-09-14 17:06:15',_binary '',1),(37,3,'【功能验证-勿留】AI导入分类测试题2','','正确','',1,569,1,1,'OPENLAB','1','2026-09-14 17:06:15','1','2026-09-14 17:06:15',_binary '',1),(38,1,'（难度：易）公司防腐保温业务的主要服务对象是下列哪一类？','[{\"key\":\"A\",\"text\":\"石化、化工、电力、市政供热等工业装置\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"家用电器制造车间\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"汽车整车装配线\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"食品冷链零售门店\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(39,1,'（难度：易）下列属于管道外防腐主流工艺的是？','[{\"key\":\"A\",\"text\":\"3PE 三层聚乙烯防腐\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"阳极氧化处理\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电镀锌\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"表面渗碳\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(40,1,'（难度：易）公司产品线中的“保温”主要解决什么问题？','[{\"key\":\"A\",\"text\":\"减少热量散失、防止冻凝与烫伤\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"提高金属导电性\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"增加结构承载能力\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"降低材料密度\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(41,1,'（难度：易）岩棉、玻璃棉、硅酸铝棉属于下列哪类材料？','[{\"key\":\"A\",\"text\":\"绝热保温材料\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"防腐涂料\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"结构钢材\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"密封胶粘剂\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(42,1,'（难度：易）环氧粉末（FBE）主要应用于下列哪个部位？','[{\"key\":\"A\",\"text\":\"管道及管件外表面的熔结防腐涂层\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"混凝土外加剂\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电缆绝缘层\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"建筑幕墙玻璃\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(43,1,'（难度：易）公司承接的防腐保温工程项目，业务链条通常起始于？','[{\"key\":\"A\",\"text\":\"现场勘查与需求确认\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"竣工结算\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"备品备件采购\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"人员招聘\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(44,1,'（难度：易）下列哪一项不属于防腐保温工程的典型客户行业？','[{\"key\":\"A\",\"text\":\"石油化工\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"电力热电\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"市政供热\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"服装零售\",\"isCorrect\":true}]','D','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(45,1,'（难度：易）3PE 防腐层中的“PE”指的是？','[{\"key\":\"A\",\"text\":\"聚乙烯\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"聚酯\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"环氧树脂\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"聚氨酯\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(46,1,'（难度：中）公司对外宣传中的“一体化解决方案”通常指？','[{\"key\":\"A\",\"text\":\"材料供应 + 施工 + 验收全过程服务\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"仅提供材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"仅提供方案设计\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"仅提供物流运输\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(47,1,'（难度：中）了解客户需求时，首要关注的信息通常是？','[{\"key\":\"A\",\"text\":\"介质温度、压力与腐蚀环境等工况条件\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"客户办公电脑的品牌\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"厂区绿化面积\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"员工平均年龄\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(48,1,'（难度：易）公司防腐保温业务通常包含下列哪些产品与服务？','[{\"key\":\"A\",\"text\":\"防腐涂料供应\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"绝热保温材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场防腐保温施工\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"工程验收技术服务\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(49,1,'（难度：中）选择防腐方案时需要重点考虑的因素有哪些？','[{\"key\":\"A\",\"text\":\"介质温度与运行工况\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"环境腐蚀性与敷设方式\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"设计使用寿命\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"管道外表面油漆颜色\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(50,1,'（难度：易）保温工程的常见应用部位包括？','[{\"key\":\"A\",\"text\":\"蒸汽与热水管道\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"储罐与塔器\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"换热设备\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"办公桌椅\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(51,1,'（难度：易）下列属于绝热保温材料的有哪些？','[{\"key\":\"A\",\"text\":\"岩棉\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"玻璃棉\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"硅酸铝棉\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"环氧富锌底漆\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(52,1,'（难度：中）与客户洽谈项目时通常需要明确的信息有哪些？','[{\"key\":\"A\",\"text\":\"工程量与工期要求\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"执行的技术标准\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场施工条件\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"结算与付款方式\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(53,1,'（难度：易）防腐与保温是两种功能不同的工程措施：前者防止腐蚀，后者减少热损失。','','对','两者目标不同，常配合使用但不可相互替代。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(54,1,'（难度：易）3PE 防腐层由环氧粉末底层、胶粘剂中间层和聚乙烯面层三层构成。','','对','这是 3PE 的标准结构。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(55,1,'（难度：易）保温材料可以脱离介质温度随意选型，与工况无关。','','错','材料耐温等级必须匹配介质温度，否则会失效甚至碳化。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(56,1,'（难度：易）FBE 是环氧粉末涂层的英文缩写。','','对','FBE 即 Fusion Bonded Epoxy。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(57,1,'（难度：易）公司的业务仅涉及涂料销售，不包含现场施工。','','错','公司业务包含现场防腐保温施工与验收技术服务。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(58,1,'（难度：易）石化、电力、市政供热等行业都属于防腐保温工程的典型服务领域。','','对','这些行业存在大量需防腐与保温的管道和设备。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(59,1,'（难度：易）熟悉公司产品线有助于现场准确识别材料与工艺。','','对','识别材料是判断工艺与质量的前提。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(60,1,'（难度：易）保温工程的目的一是减少热损失，二是防止管道冬季冻凝。','','对','防冻防凝是保温的重要功能之一。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(61,1,'（难度：中）客户的行业背景与防腐方案选择没有关系。','','错','行业决定介质与腐蚀环境，直接影响方案选择。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(62,1,'（难度：中）工程类项目通常需要现场勘查后再确定技术方案。','','对','现场条件（敷设方式、环境、空间）是方案确定的重要依据。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(63,4,'（难度：中）简述公司防腐保温业务的主要服务对象与典型应用场景。','','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(64,4,'（难度：中）简述防腐与保温两类工程措施的目的差异。','','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(65,4,'（难度：易）列举公司产品线中至少三类材料并说明其用途。','','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(66,4,'（难度：中）承接防腐保温项目时，前期需要向客户确认哪些关键信息？','','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(67,4,'（难度：中）为什么现场人员需要了解公司业务全景与产品线？','','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(68,5,'（难度：中）某化工厂反映“蒸汽管道外面包了保温棉，但人员仍被烫伤”。请分析可能原因并提出处理思路。','','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(69,4,'（难度：易）项目部准备承接一个新建化工厂的蒸汽管道保温工程，请列出开工前需要收集的基本信息。','','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(70,5,'（难度：中）现场新员工把岩棉当成了“防腐涂料”准备刷在设备表面。请指出错误并说明正确做法。','','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(71,5,'（难度：中）客户问：“你们的 3PE 防腐和普通刷漆有什么区别？”请用通俗语言解释。','','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(72,5,'（难度：中）某市政供热工程要求必须在采暖季前完工，作为刚入职的现场人员，你应重点关注哪些业务环节？','','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。',2,570,1,1,'OPENLAB','1','2026-09-14 17:23:01','1','2026-09-15 16:59:23',_binary '',1),(73,1,'（难度：易）公司防腐保温业务的主要服务对象是下列哪一类？','[{\"key\":\"A\",\"text\":\"石化、化工、电力、市政供热等工业装置\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"家用电器制造车间\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"汽车整车装配线\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"食品冷链零售门店\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(74,1,'（难度：易）下列属于管道外防腐主流工艺的是？','[{\"key\":\"A\",\"text\":\"3PE 三层聚乙烯防腐\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"阳极氧化处理\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电镀锌\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"表面渗碳\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(75,1,'（难度：易）公司产品线中的“保温”主要解决什么问题？','[{\"key\":\"A\",\"text\":\"减少热量散失、防止冻凝与烫伤\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"提高金属导电性\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"增加结构承载能力\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"降低材料密度\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(76,1,'（难度：易）岩棉、玻璃棉、硅酸铝棉属于下列哪类材料？','[{\"key\":\"A\",\"text\":\"绝热保温材料\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"防腐涂料\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"结构钢材\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"密封胶粘剂\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(77,1,'（难度：易）环氧粉末（FBE）主要应用于下列哪个部位？','[{\"key\":\"A\",\"text\":\"管道及管件外表面的熔结防腐涂层\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"混凝土外加剂\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"电缆绝缘层\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"建筑幕墙玻璃\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(78,1,'（难度：易）公司承接的防腐保温工程项目，业务链条通常起始于？','[{\"key\":\"A\",\"text\":\"现场勘查与需求确认\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"竣工结算\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"备品备件采购\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"人员招聘\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(79,1,'（难度：易）下列哪一项不属于防腐保温工程的典型客户行业？','[{\"key\":\"A\",\"text\":\"石油化工\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"电力热电\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"市政供热\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"服装零售\",\"isCorrect\":true}]','D','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(80,1,'（难度：易）3PE 防腐层中的“PE”指的是？','[{\"key\":\"A\",\"text\":\"聚乙烯\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"聚酯\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"环氧树脂\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"聚氨酯\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(81,1,'（难度：中）公司对外宣传中的“一体化解决方案”通常指？','[{\"key\":\"A\",\"text\":\"材料供应 + 施工 + 验收全过程服务\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"仅提供材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"仅提供方案设计\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"仅提供物流运输\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(82,1,'（难度：中）了解客户需求时，首要关注的信息通常是？','[{\"key\":\"A\",\"text\":\"介质温度、压力与腐蚀环境等工况条件\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"客户办公电脑的品牌\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"厂区绿化面积\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"员工平均年龄\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(83,1,'（难度：易）公司防腐保温业务通常包含下列哪些产品与服务？','[{\"key\":\"A\",\"text\":\"防腐涂料供应\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"绝热保温材料供应\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场防腐保温施工\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"工程验收技术服务\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(84,1,'（难度：中）选择防腐方案时需要重点考虑的因素有哪些？','[{\"key\":\"A\",\"text\":\"介质温度与运行工况\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"环境腐蚀性与敷设方式\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"设计使用寿命\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"管道外表面油漆颜色\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(85,1,'（难度：易）保温工程的常见应用部位包括？','[{\"key\":\"A\",\"text\":\"蒸汽与热水管道\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"储罐与塔器\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"换热设备\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"办公桌椅\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(86,1,'（难度：易）下列属于绝热保温材料的有哪些？','[{\"key\":\"A\",\"text\":\"岩棉\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"玻璃棉\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"硅酸铝棉\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"环氧富锌底漆\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(87,1,'（难度：中）与客户洽谈项目时通常需要明确的信息有哪些？','[{\"key\":\"A\",\"text\":\"工程量与工期要求\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"执行的技术标准\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"现场施工条件\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"结算与付款方式\",\"isCorrect\":false}]','A','',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(88,1,'（难度：易）防腐与保温是两种功能不同的工程措施：前者防止腐蚀，后者减少热损失。','','对','两者目标不同，常配合使用但不可相互替代。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(89,1,'（难度：易）3PE 防腐层由环氧粉末底层、胶粘剂中间层和聚乙烯面层三层构成。','','对','这是 3PE 的标准结构。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(90,1,'（难度：易）保温材料可以脱离介质温度随意选型，与工况无关。','','错','材料耐温等级必须匹配介质温度，否则会失效甚至碳化。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(91,1,'（难度：易）FBE 是环氧粉末涂层的英文缩写。','','对','FBE 即 Fusion Bonded Epoxy。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(92,1,'（难度：易）公司的业务仅涉及涂料销售，不包含现场施工。','','错','公司业务包含现场防腐保温施工与验收技术服务。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(93,1,'（难度：易）石化、电力、市政供热等行业都属于防腐保温工程的典型服务领域。','','对','这些行业存在大量需防腐与保温的管道和设备。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(94,1,'（难度：易）熟悉公司产品线有助于现场准确识别材料与工艺。','','对','识别材料是判断工艺与质量的前提。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(95,1,'（难度：易）保温工程的目的一是减少热损失，二是防止管道冬季冻凝。','','对','防冻防凝是保温的重要功能之一。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(96,1,'（难度：中）客户的行业背景与防腐方案选择没有关系。','','错','行业决定介质与腐蚀环境，直接影响方案选择。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(97,1,'（难度：中）工程类项目通常需要现场勘查后再确定技术方案。','','对','现场条件（敷设方式、环境、空间）是方案确定的重要依据。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(98,4,'（难度：中）简述公司防腐保温业务的主要服务对象与典型应用场景。','','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(99,4,'（难度：中）简述防腐与保温两类工程措施的目的差异。','','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(100,4,'（难度：易）列举公司产品线中至少三类材料并说明其用途。','','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(101,4,'（难度：中）承接防腐保温项目时，前期需要向客户确认哪些关键信息？','','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。','需确认介质温度与压力、腐蚀环境与敷设方式、工程量与工期、设计寿命与执行标准、现场施工条件（脚手架、动火、用水用电限制）、验收要求与结算方式。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(102,4,'（难度：中）为什么现场人员需要了解公司业务全景与产品线？','','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(103,5,'（难度：中）某化工厂反映“蒸汽管道外面包了保温棉，但人员仍被烫伤”。请分析可能原因并提出处理思路。','','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(104,4,'（难度：易）项目部准备承接一个新建化工厂的蒸汽管道保温工程，请列出开工前需要收集的基本信息。','','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(105,5,'（难度：中）现场新员工把岩棉当成了“防腐涂料”准备刷在设备表面。请指出错误并说明正确做法。','','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:03','1','2026-09-15 16:59:23',_binary '',1),(106,5,'（难度：中）客户问：“你们的 3PE 防腐和普通刷漆有什么区别？”请用通俗语言解释。','','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:04','1','2026-09-15 16:59:23',_binary '',1),(107,5,'（难度：中）某市政供热工程要求必须在采暖季前完工，作为刚入职的现场人员，你应重点关注哪些业务环节？','','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。',2,570,1,1,'OPENLAB','1','2026-09-15 16:04:04','1','2026-09-15 16:59:23',_binary '',1),(108,1,'根据GB30871，下列哪一项不属于特殊作业（　）？','[{\"key\":\"A\",\"text\":\"受限空间作业\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"办公室文件整理\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"动火作业\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"高处作业\",\"isCorrect\":false}]','B','受限空间、动火、高处作业均属于特殊作业范畴。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(109,1,'“自检、互检、专检”三检制，主要应用于哪类管理（　）？','[{\"key\":\"A\",\"text\":\"财务管理\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"质量管理\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"采购管理\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"档案管理\",\"isCorrect\":false}]','B','三检制用于施工过程质量管控。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(110,1,'受限空间作业，作业票证审批完成后，票证有效期应当以（　）要求为准。','[{\"key\":\"A\",\"text\":\"GB30871规范\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"员工经验\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"随意填写\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"口头约定\",\"isCorrect\":false}]','A','作业票证有效期按GB30871等规范要求执行。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(111,1,'劳动防护用品PPE使用管理主体责任是（　）。','[{\"key\":\"A\",\"text\":\"作业人员及现场管理人员\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"保洁人员\",\"isCorrect\":false},{\"key\":\"C\",\"text\":\"后勤食堂\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"行政文员\",\"isCorrect\":false}]','A','作业人员与现场管理人员共同承担PPE使用管理责任。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(112,1,'发生现场事故后首要优先工作是（　）。','[{\"key\":\"A\",\"text\":\"整理资料归档\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"人员应急处置与逃生避险\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"编写报告归档\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"召开复盘会议\",\"isCorrect\":false}]','B','事故发生后应优先处置人员安全与现场避险。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(113,2,'属于A域应急与事故课程包含的内容有（　）。','[{\"key\":\"A\",\"text\":\"现场应急处置逃生\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"典型事故案例复盘\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"涂料配比调试\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"应急演练实施\",\"isCorrect\":true}]','A,B,D','应急与事故课程包含应急处置、案例复盘与演练。',2,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(114,2,'特殊作业许可包含下面哪些作业（　）。','[{\"key\":\"A\",\"text\":\"受限空间作业\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"高处脚手架作业\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"动火作业\",\"isCorrect\":true},{\"key\":\"D\",\"text\":\"临时用电作业\",\"isCorrect\":true}]','A,B,C,D','受限空间、高处、动火、临时用电均属特殊作业。',2,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(115,2,'施工影像留证规范对资料管理要求包含（　）。','[{\"key\":\"A\",\"text\":\"影像真实可追溯\",\"isCorrect\":true},{\"key\":\"B\",\"text\":\"资料及时归档\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"可以后期随意修改原始照片\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"按要求组卷移交\",\"isCorrect\":true}]','A,B,D','影像须真实可追溯、及时归档并按要求组卷移交。',2,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(116,3,'新员工入职培训只学习操作技能，不需要学习岗位职责和职业行为规范。',NULL,'错','入职培训需同时学习岗位职责与职业行为规范。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(117,3,'粉尘、溶剂作业岗位，需要开展职业健康危害防护培训。',NULL,'对','职业健康防护属HSE基础必修内容。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(118,3,'三检制即自检、互检、专检，目的是对施工过程质量进行管控。',NULL,'对','三检制用于过程质量管控。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(119,3,'特殊作业可以先开工，后补办作业票。',NULL,'错','特殊作业必须先审批后作业。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(120,3,'事故案例复盘目的是吸取教训，避免同类事故重复发生。',NULL,'对','案例复盘用于学习教训、防范重复事故。',1,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(121,4,'简述受限空间（储罐/塔罐内部）完整作业流程要点。',NULL,'办理受限空间作业票证审批；作业前先通风再气体检测合格；落实专人监护与安全防护措施；作业过程持续监测与监护；完工后进行验收与清场。','按作业票证、气体检测、监护三大要点评分。',3,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(122,4,'简述三检制在施工现场如何落地执行。',NULL,'明确各环节检验责任人：自检由作业班组完成、互检由上下工序间交接检验、专检由专职质检人员检验，各环节留存检验记录并签字确认。','按自检、互检、专检三个环节评分。',2,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(123,5,'某项目储罐内部开展检修作业，作业人员未办理受限空间作业票，未做气体检测直接进入罐内作业；现场无监护人员，作业过程发生人员中毒。',NULL,'违章问题：未办理受限空间作业票、未做气体检测、现场无监护人员。正确措施：办理受限空间作业票并审批；先通风、再检测、合格后作业；落实专人监护与应急救援准备；作业过程持续监测。','考核受限空间作业票证、气体检测、专人监护三大管控要点。',3,NULL,1,1,'OPENLAB','1','2026-09-17 14:14:52','1','2026-09-17 14:14:52',_binary '\0',1),(124,1,'Sa/St是用来判定（　）指标。','[{\"key\":\"A\",\"text\":\"保温厚度\",\"isCorrect\":false},{\"key\":\"B\",\"text\":\"钢材除锈表面等级\",\"isCorrect\":true},{\"key\":\"C\",\"text\":\"涂层干膜厚度\",\"isCorrect\":false},{\"key\":\"D\",\"text\":\"管材压力