CREATE TABLE `training_study_behavior_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `user_id` bigint NOT NULL COMMENT '学员用户ID',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学员姓名',
  `study_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学习类型：video/document/live/vr',
  `resource_id` bigint DEFAULT NULL COMMENT '资源ID',
