/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_video_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '视频资源ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '视频标题',
  `category_id` bigint DEFAULT NULL COMMENT '所属分类ID',
  `video_type` tinyint DEFAULT '2' COMMENT '视频类型：1 短视频 2 录播',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL（可选）',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件相对存储路径（uploads/resource 下）',
  `file_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件类型：mp4/mov',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `duration_seconds` int DEFAULT NULL COMMENT '视频时长（秒，上传时前端提供或后续解析）',
  `definition` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始清晰度：2160P/1080P/720P/480P/360P',
  `definition_options` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可播放清晰度列表(JSON)：[{definition,url,transcoded}]，用于弱网切换低清晰度',
  `transcode_status` tinyint NOT NULL DEFAULT '0' COMMENT '转码状态：0未转码 1排队 2处理中 3成功 4失败',
  `credit_hours` decimal(5,2) DEFAULT NULL COMMENT '学时值（独立配置）',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签（逗号分隔）',
  `status` tinyint NOT NULL DEFAULT '2' COMMENT '状态：1草稿 2上线 3下架 4归档',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '播放次数',
  `uploader_id` bigint DEFAULT NULL COMMENT '上传人ID',
  `uploader_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上传人姓名',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tvr_category` (`category_id`),
  KEY `idx_tvr_status` (`status`),
  KEY `idx_tvr_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='视频资源表';
