DROP TABLE IF EXISTS `training_video_transcode_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_video_transcode_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `video_id` bigint NOT NULL COMMENT '视频资源ID',
  `definition` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标清晰度：2160P/1080P/720P/480P/360P',
  `height` int DEFAULT NULL COMMENT '目标画面高度（像素）',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '任务状态：0待转码 1转码中 2成功 3失败 4跳过',
  `progress` int NOT NULL DEFAULT '0' COMMENT '进度百分比（0-100）',
  `source_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '源文件相对路径',
  `output_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转码输出相对路径',
  `file_size` bigint DEFAULT NULL COMMENT '输出文件大小（字节）',
  `command` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ffmpeg 执行命令（排障用）',
  `error_msg` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `creator` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_tvtt_video` (`video_id`),
  KEY `idx_tvtt_video_definition` (`video_id`,`definition`),
  KEY `idx_tvtt_status` (`status`),
  KEY `idx_tvtt_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='视频转码任务表';
/*!40101 SET character_set_client = @saved_cs_client */;

